'use strict'

// The engine half of the `@dcl/inspector` stand-in: an `@dcl/ecs` engine that
// knows every component the real editor knows.
//
// Ported from upstream `src/lib/data-layer/host/utils/engine.ts` plus
// `src/lib/sdk/components/index.ts`'s `createComponents` /
// `createEditorComponents`, with one substitution: upstream reaches into
// `@dcl/asset-packs` and its own `versioning/registry` for the 31 non-core
// component schemas; we read them from `component-schemas.json`, a pinned
// snapshot regenerated by `scripts/dump-inspector-tables.cjs`.
//
// Defining ALL of them is not tidiness — it is correctness. `@dcl/ecs`'s crdt
// receive loop (`dist-cjs/systems/crdt/index.js`) does
// `engine.getComponentOrNull(msg.componentId)` and, when that is null, only
// re-broadcasts the message: `updateFromCrdt` is never called, so the value
// never enters the engine and the next save cannot see it. An editor writing a
// component we never defined would have its edit accepted, echoed back, and
// then silently dropped on save.

const ECS = require('@dcl/ecs/dist-cjs')
const { ReadWriteByteBuffer } = require('@dcl/ecs/dist-cjs/serialization/ByteBuffer')

const TABLE = require('./component-schemas.json')

/**
 * Component name -> the `@dcl/ecs` factory that produces it.
 *
 * `ECS.components` is a real export — 190 factories — that neither `dist` nor
 * `dist-cjs` declares, so it is read through a cast rather than left to widen
 * the whole module to `any`. The `|| {}` is the load-bearing half: should a
 * future `@dcl/ecs` drop or rename it, every `defineFrom: 'ecs'` entry lands in
 * `missing` and `defineComponents` throws by name, instead of an engine that
 * boots without its protobuf-backed components and drops edits on save.
 *
 * @returns {Map<string, (engine: any) => { componentName?: string }>}
 */
function ecsFactories() {
  const probe = ECS.Engine()
  const byName = new Map()
  const factories = /** @type {Record<string, unknown>} */ (
    /** @type {any} */ (ECS).components || {}
  )
  for (const factory of Object.values(factories)) {
    if (typeof factory !== 'function') continue
    try {
      const def = factory(probe)
      if (def && def.componentName) byName.set(def.componentName, factory)
    } catch {
      // Not a component factory, or one that needs arguments.
    }
  }
  return byName
}

let FACTORIES = null

/**
 * Define the editor's whole component set on `engine`, in upstream's order.
 *
 * Order is load-bearing: `dumpEngineToComposite` walks `componentsIter()`, so
 * definition order is the order component groups land in the saved
 * `.composite`. Matching upstream keeps a scene from churning in git the first
 * time it is saved through this host.
 *
 * @param {import('@dcl/ecs/dist-cjs').IEngine} engine
 */
function defineComponents(engine) {
  if (!FACTORIES) FACTORIES = ecsFactories()
  const missing = []
  for (const entry of TABLE.components) {
    if (engine.getComponentOrNull(entry.name)) continue
    if (entry.defineFrom === 'ecs') {
      // Protobuf-backed (and `core::Transform`'s bespoke) codecs cannot be
      // rebuilt from a jsonSchema, so these MUST come from `@dcl/ecs` itself.
      const factory = FACTORIES.get(entry.name)
      if (!factory) {
        missing.push(entry.name)
        continue
      }
      factory(engine)
    } else {
      // `component-schemas.json` is a pinned snapshot, so its `type` fields
      // widen to `string` on import where `JsonSchemaExtended` wants literal
      // unions. `Schemas.fromJson` is the validator for that shape — asserting
      // it here would only move the check earlier and duplicate it.
      const schema = /** @type {any} */ (entry.jsonSchema)
      engine.defineComponentFromSchema(entry.name, ECS.Schemas.fromJson(schema))
    }
  }
  if (missing.length) {
    throw new Error(
      'the vendored @dcl/ecs does not define ' +
        missing.join(', ') +
        ', which @dcl/inspector ' +
        TABLE.inspectorVersion +
        ' expects. Re-run scripts/dump-inspector-tables.cjs against a matching ' +
        '@dcl/inspector, or install the real package in the scene.'
    )
  }
}

/**
 * Types come from `dist-cjs`, which is what line 21 requires and therefore what
 * these values actually are. `@dcl/ecs` resolves to `dist`, whose `IEngine` is
 * a structurally identical but nominally distinct type: annotate against it and
 * every call that crosses this boundary is a type error about two spellings of
 * the same interface.
 *
 * @param {import('@dcl/ecs/dist-cjs').IEngineOptions} [opts]
 * @returns {{ engine: import('@dcl/ecs/dist-cjs').IEngine }}
 */
function createEngineContext(opts) {
  const engine = ECS.Engine(opts)
  defineComponents(engine)
  // Upstream returns the named component handles too. Nothing in this host
  // needs them — the minimal composite is shipped as JSON rather than built
  // from `Nodes`/`SceneMetadata` handles — so the shape is `{ engine }` only.
  return { engine }
}

/**
 * Every component's crdt state, as the editor's first stream message.
 *
 * @param {import('@dcl/ecs/dist-cjs').IEngine} engine
 * @returns {Uint8Array}
 */
function serializeEngine(engine) {
  const messages = new ReadWriteByteBuffer()
  for (const component of engine.componentsIter()) {
    component.dumpCrdtStateToBuffer(messages)
  }
  return messages.toBinary()
}

module.exports = { ECS, createEngineContext, defineComponents, serializeEngine, TABLE }
